//! Integration tests for `pkix_revocation::OcspChecker`.
//!
//! All DER fixtures in tests/fixtures/ocsp-*.der were generated by
//! `gen_ocsp_fixtures.py` using pyca/cryptography as the external oracle.
//! Tests run fully offline.
//!
//! Fixture structure:
//!   ocsp-ca.der              — RSA-2048 self-signed OCSP CA (serial=100)
//!   ocsp-leaf-good.der       — leaf cert, serial=1 (not revoked)
//!   ocsp-leaf-revoked.der    — leaf cert, serial=2 (revoked in response fixtures)
//!   ocsp-good.der            — OCSP response: serial=1 → good
//!   ocsp-revoked.der         — OCSP response: serial=2 → revoked, reason=keyCompromise(1)
//!   ocsp-revoked-no-reason.der — OCSP response: serial=2 → revoked, no reason
//!   ocsp-unknown.der         — OCSP response: serial=1 → unknown
//!   ocsp-expired.der         — OCSP response: nextUpdate=2021-01-01 (expired)
//!   ocsp-bad-sig.der         — ocsp-good.der with last signature byte corrupted
//!
//! Cross-CA replay fixtures (generated by `gen_ocsp_cross_ca_fixture.py)`:
//!   ocsp-ca-a.der            — CA-A cert (RSA-2048, CN=OCSP CA-A)
//!   ocsp-ca-b.der            — CA-B cert (RSA-2048, CN=OCSP CA-B)
//!   ocsp-ca-a-leaf.der       — leaf issued by CA-A, serial=1
//!   ocsp-ca-b-leaf.der       — leaf issued by CA-B, serial=1
//!   ocsp-ca-a-good.der       — OCSP "good" for CA-A/serial=1 (issuerNameHash/issuerKeyHash = CA-A)
//!
//! `ResponderId` fixtures (generated by `gen_responder_id_fixtures.py`, PKIX-jd7):
//!   ocsp-rid-ca.der          — RSA-2048 CA for `ResponderId` tests (CN=OCSP RID Test CA)
//!   ocsp-rid-leaf-good.der   — leaf issued by ocsp-rid-ca.der, serial=1
//!   ocsp-rid-good-byname.der — valid response, ResponderId=byName(correct CA name)
//!   ocsp-rid-good-bykey.der  — valid response, ResponderId=byKey(SHA1 of CA SPKI bits)
//!   ocsp-rid-bad-byname.der  — response with byName(CN=Wrong CA), signed with correct key
//!   ocsp-rid-bad-bykey.der   — response with byKey(corrupted SHA1), signed with correct key
//!
//! Delegated-OCSP fixtures (generated by `gen_ocsp_delegated_fixtures.py`, PKIX-53kt):
//!   ocsp-delegated-ca.der            — separate CA used by the delegated family
//!   ocsp-delegated-leaf.der          — leaf cert issued by ocsp-delegated-ca.der
//!   ocsp-delegated-good.der          — valid delegated response (responder cert
//!                                      with OCSPSigning EKU embedded in basic.certs)
//!   ocsp-delegated-no-eku.der        — delegated response, responder cert lacks
//!                                      OCSPSigning EKU
//!   ocsp-delegated-wrong-ca.der      — delegated response, responder cert signed by
//!                                      a different CA than the leaf's issuer
//!   ocsp-delegated-expired-cert.der  — delegated response, responder cert validity
//!                                      ends before producedAt
//!   ocsp-delegated-bad-sig.der       — delegated response, issuer's signature on
//!                                      embedded responder cert is corrupted
//!
//! Validation time: 2026-06-01 00:00:00 UTC = `1_780_272_000`.
//! All valid OCSP responses have producedAt=2026-01-01, nextUpdate=2027-01-01.

use der::Decode as _;
use pkix_path::{DefaultVerifier, TrustAnchor};
use pkix_revocation::{Error, OcspChecker, RevocationChecker as _};
use x509_cert::{ext::pkix::crl::CrlReason, Certificate};

/// Unix timestamp used as "now" for all tests (2026-06-01 00:00:00 UTC).
const NOW: u64 = 1_780_272_000;

fn fixture(name: &str) -> Vec<u8> {
    let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    std::fs::read(&path).unwrap_or_else(|e| panic!("read {name}: {e}"))
}

fn load_cert(name: &str) -> Certificate {
    let der = fixture(name);
    Certificate::from_der(&der).unwrap_or_else(|e| panic!("parse {name}: {e}"))
}

fn checker(response_name: &str) -> OcspChecker<DefaultVerifier> {
    OcspChecker::new(fixture(response_name), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response")
}

// ---------------------------------------------------------------------------
// Happy path
// ---------------------------------------------------------------------------

/// Good cert (serial=1) against ocsp-good.der → Ok(()).
///
/// Oracle: pyca/cryptography; certStatus=good for serial=1.
#[test]
fn ocsp_good_cert_ok() {
    let ca = load_cert("ocsp-ca.der");
    let good = load_cert("ocsp-leaf-good.der");
    let result = checker("ocsp-good.der").check_revocation(&good, &ca);
    result.expect("good cert must return Ok(())");
}

// ---------------------------------------------------------------------------
// Revoked
// ---------------------------------------------------------------------------

/// Revoked cert (serial=2) against ocsp-revoked.der → Err(Revoked { reason=Some(KeyCompromise) }).
///
/// Oracle: pyca/cryptography; certStatus=revoked, CRLReason=keyCompromise (RFC 5280 §5.3.1 value 1).
#[test]
fn ocsp_cert_revoked_with_reason() {
    let ca = load_cert("ocsp-ca.der");
    let revoked = load_cert("ocsp-leaf-revoked.der");
    let result = checker("ocsp-revoked.der").check_revocation(&revoked, &ca);
    assert!(
        matches!(
            result,
            Err(Error::Revoked {
                reason_code: Some(CrlReason::KeyCompromise),
                ..
            })
        ),
        "revoked cert must return Revoked {{ reason_code: Some(KeyCompromise) }}, got: {result:?}"
    );
}

/// Revoked cert (serial=2) against ocsp-revoked-no-reason.der → Err(Revoked { reason=None }).
///
/// Oracle: pyca/cryptography; certStatus=revoked, no `CRLReason` extension.
#[test]
fn ocsp_cert_revoked_no_reason() {
    let ca = load_cert("ocsp-ca.der");
    let revoked = load_cert("ocsp-leaf-revoked.der");
    let result = checker("ocsp-revoked-no-reason.der").check_revocation(&revoked, &ca);
    assert!(
        matches!(
            result,
            Err(Error::Revoked {
                reason_code: None,
                ..
            })
        ),
        "revoked cert (no reason) must return Revoked {{ reason_code: None }}, got: {result:?}"
    );
}

