/// Valid cert against ocsp-expired.der (nextUpdate=2021-01-01 < NOW=2026) → Err(OcspExpired).
///
/// Oracle: ocsp-expired.der has nextUpdate=2021-01-01 08:00:00 UTC.
#[test]
fn ocsp_expired_response_returns_error() {
    let ca = load_cert("ocsp-ca.der");
    let good = load_cert("ocsp-leaf-good.der");
    let result = checker("ocsp-expired.der").check_revocation(&good, &ca);
    assert!(
        matches!(result, Err(Error::OcspExpired)),
        "expired OCSP response must return OcspExpired, got: {result:?}"
    );
}

// ---------------------------------------------------------------------------
// Signature errors
// ---------------------------------------------------------------------------

/// Valid cert against ocsp-bad-sig.der → Err(OcspSignatureInvalid).
///
/// Oracle: ocsp-bad-sig.der is ocsp-good.der with last signature byte XOR'd 0xFF.
#[test]
fn ocsp_bad_signature_returns_error() {
    let ca = load_cert("ocsp-ca.der");
    let good = load_cert("ocsp-leaf-good.der");
    let result = checker("ocsp-bad-sig.der").check_revocation(&good, &ca);
    assert!(
        matches!(result, Err(Error::OcspSignatureInvalid)),
        "corrupted OCSP signature must return OcspSignatureInvalid, got: {result:?}"
    );
}

// ---------------------------------------------------------------------------
// Issuer hash verification (PKIX-8sh.4)
// ---------------------------------------------------------------------------

/// Cross-CA replay: CA-A's "good" response for serial=1 must NOT validate
/// CA-B's serial=1 cert even though the serial matches.
///
/// The response's CertID.issuerNameHash and issuerKeyHash were computed from
/// CA-A. When verified against CA-B as issuer, the signature or `CertID` hash check
/// fails → some Err variant (`OcspSignatureInvalid` or `OcspCertIdMismatch`).
///
/// Oracle: pyca/cryptography (`gen_ocsp_cross_ca_fixture.py`).
/// Fixtures: ocsp-ca-a.der, ocsp-ca-b.der, ocsp-ca-b-leaf.der, ocsp-ca-a-good.der.
#[test]
fn ocsp_cross_ca_replay_rejected() {
    let ca_b = load_cert("ocsp-ca-b.der");
    let ca_b_leaf = load_cert("ocsp-ca-b-leaf.der");
    // Use CA-A's response (signed by CA-A's key) against CA-B's leaf.
    // The verifier here is CA-A's key (supplied as a dummy verifier that won't
    // be reached because the signature check uses the issuer SPKI — CA-B here).
    // We use DefaultVerifier; the sig check will fail first OR the hash check
    // fires: either way the response must not return Ok(()).
    //
    // To isolate the issuer-hash check specifically we need the signature to
    // pass. Build a checker using CA-A's response but supply CA-B as issuer:
    // the sig was made with CA-A's key, CA-B has a different key → sig fails
    // before we reach the hash check.
    //
    // The test verifies the combined defence: at minimum, no Ok(()) is returned
    // when the wrong issuer is supplied.
    let checker = OcspChecker::new(fixture("ocsp-ca-a-good.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation(&ca_b_leaf, &ca_b);
    assert!(
        result.is_err(),
        "cross-CA replay must not return Ok(()); got: {result:?}"
    );
    assert!(
        !matches!(result, Ok(())),
        "cross-CA replay must be rejected"
    );
}

/// Same-CA happy path: CA-A's response for CA-A's own leaf must pass.
///
/// Oracle: pyca/cryptography (`gen_ocsp_cross_ca_fixture.py`).
#[test]
fn ocsp_same_ca_issuer_hash_ok() {
    let ca_a = load_cert("ocsp-ca-a.der");
    let ca_a_leaf = load_cert("ocsp-ca-a-leaf.der");
    let checker = OcspChecker::new(fixture("ocsp-ca-a-good.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation(&ca_a_leaf, &ca_a);
    result.expect("CA-A's response for CA-A's own leaf must return Ok(())");
}

// ---------------------------------------------------------------------------
// Parse errors
// ---------------------------------------------------------------------------

/// Truncated OCSP DER → Err(OcspParseError(_)).
#[test]
fn ocsp_parse_error_truncated_der() {
    // Parse errors now surface at construction (the response is decoded once
    // and cached), not at check_revocation. The `OcspParseError` variant is
    // still the expected error, exactly as before.
    let _ca = load_cert("ocsp-ca.der");
    let _good = load_cert("ocsp-leaf-good.der");
    let truncated = vec![0x30, 0x82, 0x01, 0x00, 0xAA, 0xBB];
    let result = OcspChecker::new(truncated, NOW, DefaultVerifier);
    assert!(
        matches!(result, Err(Error::OcspParseError(_))),
        "truncated OCSP response must return OcspParseError, got: {result:?}"
    );
}

// ---------------------------------------------------------------------------
// ResponderId verification (PKIX-jd7)
// ---------------------------------------------------------------------------

/// Valid response with ResponderId=byName(correct CA name) → Ok(()).
///
/// Oracle: pyca/cryptography (`gen_responder_id_fixtures.py`).
/// Fixture: ocsp-rid-good-byname.der has ResponderId=byName(CN=OCSP RID Test CA).
#[test]
fn ocsp_responder_id_byname_correct_accepted() {
    let ca = load_cert("ocsp-rid-ca.der");
    let leaf = load_cert("ocsp-rid-leaf-good.der");
    let checker = OcspChecker::new(fixture("ocsp-rid-good-byname.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation(&leaf, &ca);
    result.expect("byName ResponderId matching issuer subject must return Ok(())");
}

/// Valid response with ResponderId=byKey(SHA-1 of CA SPKI) → Ok(()).
///
/// Oracle: pyca/cryptography (`gen_responder_id_fixtures.py`).
/// Fixture: ocsp-rid-good-bykey.der has ResponderId=byKey(SHA1(CA SPKI bits)).
#[test]
fn ocsp_responder_id_bykey_correct_accepted() {
    let ca = load_cert("ocsp-rid-ca.der");
    let leaf = load_cert("ocsp-rid-leaf-good.der");
    let checker = OcspChecker::new(fixture("ocsp-rid-good-bykey.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation(&leaf, &ca);
    result.expect("byKey ResponderId matching issuer SPKI SHA-1 must return Ok(())");
}

/// Response with ResponderId=byName(CN=Wrong CA), signed with correct key → Err(OcspResponderIdMismatch).
///
/// The signature verifies (correct key) but the `ResponderId` name does not match
/// the issuer's subject DN (CN=Wrong CA ≠ CN=OCSP RID Test CA).
///
/// Oracle: pyca/cryptography (`gen_responder_id_fixtures.py`).
/// Fixture: ocsp-rid-bad-byname.der has byName=CN=Wrong CA, signed by ocsp-rid-ca key.
#[test]
fn ocsp_responder_id_byname_wrong_rejected() {
    let ca = load_cert("ocsp-rid-ca.der");
    let leaf = load_cert("ocsp-rid-leaf-good.der");
    let checker = OcspChecker::new(fixture("ocsp-rid-bad-byname.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation(&leaf, &ca);
    assert!(
        matches!(result, Err(Error::OcspResponderIdMismatch)),
        "byName ResponderId mismatch must return OcspResponderIdMismatch, got: {result:?}"
    );
}

/// Response with ResponderId=byKey(corrupted SHA-1) → Err(OcspResponderIdMismatch).
///
/// The byKey hash is inside `tbs_response_data` (the signed portion). After
/// the delegated-OCSP refactor (PKIX-53kt), `ResponderId` matching is performed
/// during signing-key resolution, BEFORE the response signature is verified.
/// A corrupted byKey is therefore reported as `OcspResponderIdMismatch` (the
/// more specific error) rather than `OcspSignatureInvalid` (which would be the
/// downstream consequence). Both errors reject the response; the new variant
/// gives callers more accurate diagnostics about why.
///
/// Oracle: pyca/cryptography (`gen_responder_id_fixtures.py`).
/// Fixture: ocsp-rid-bad-bykey.der has byKey with first SHA-1 byte XOR 0xFF.
#[test]
fn ocsp_responder_id_bykey_wrong_rejected() {
    let ca = load_cert("ocsp-rid-ca.der");
    let leaf = load_cert("ocsp-rid-leaf-good.der");
    let checker = OcspChecker::new(fixture("ocsp-rid-bad-bykey.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation(&leaf, &ca);
    assert!(
        matches!(result, Err(Error::OcspResponderIdMismatch)),
        "corrupted byKey is detected during signing-key resolution → \
         OcspResponderIdMismatch, got: {result:?}"
    );
}

// ---------------------------------------------------------------------------
// check_revocation_against_anchor (PKIX-x1i / OCSP path)
// ---------------------------------------------------------------------------

/// `check_revocation_against_anchor` with a valid OCSP response and byName `ResponderId`
/// for a cert issued by the anchor → Ok(()).
///
/// Reuses the ocsp-rid-* fixtures: ocsp-rid-ca.der is treated as the trust
/// anchor, ocsp-rid-leaf-good.der as the cert issued by that anchor.
/// ocsp-rid-good-byname.der is a valid response for that leaf from the anchor CA.
///
/// Oracle: pyca/cryptography (`gen_responder_id_fixtures.py`).
#[test]
fn ocsp_check_revocation_against_anchor_good() {
    let anchor_cert = load_cert("ocsp-rid-ca.der");
    let anchor = TrustAnchor::from(&anchor_cert);
    let leaf = load_cert("ocsp-rid-leaf-good.der");
    let checker = OcspChecker::new(fixture("ocsp-rid-good-byname.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation_against_anchor(&leaf, &anchor);
    result.expect("valid OCSP response for anchor-issued cert must return Ok(())");
}

// ---------------------------------------------------------------------------
// Delegated OCSP responder (PKIX-53kt — RFC 6960 §4.2.2.2)
// ---------------------------------------------------------------------------

/// Valid delegated OCSP response — the responder cert is embedded in the
/// response's `certs` field, has the `id-kp-OCSPSigning` EKU, is signed by
/// the issuer CA, and is valid at `producedAt`. The OCSP response signature
/// is made by the responder cert's key, NOT the issuer's key.
///
/// Independent oracle: pyca/cryptography (`gen_ocsp_delegated_fixtures.py`).
/// Pyca's `OCSPResponseBuilder.sign(responder_key, ...)` produces the
/// response; pyca's signature is the ground truth.
#[test]
fn ocsp_delegated_good_responder_accepted() {
    let ca = load_cert("ocsp-delegated-ca.der");
    let leaf = load_cert("ocsp-delegated-leaf.der");
    let result = checker("ocsp-delegated-good.der").check_revocation(&leaf, &ca);
    result.expect("valid delegated OCSP response must return Ok(())");
}

/// Delegated response where the embedded responder cert lacks the
/// `id-kp-OCSPSigning` EKU. RFC 6960 §4.2.2.2 requires this EKU on a
/// designated-responder cert. Without it, no cert in the response chain
/// is authorized to sign OCSP responses.
///
/// Expected: `Err(OcspResponderEkuMissing)`.
#[test]
fn ocsp_delegated_responder_no_eku_rejected() {
    let ca = load_cert("ocsp-delegated-ca.der");
    let leaf = load_cert("ocsp-delegated-leaf.der");
    let result = checker("ocsp-delegated-no-eku.der").check_revocation(&leaf, &ca);
    assert!(
        matches!(result, Err(Error::OcspResponderEkuMissing)),
        "responder cert without OCSPSigning EKU must be rejected → \
         OcspResponderEkuMissing, got: {result:?}"
    );
}

/// Delegated response where the embedded responder cert is signed by a
/// DIFFERENT CA than the leaf's issuer. This is the "rogue OCSP
/// responder" attack: an attacker obtains an OCSP-signing cert from any
/// CA and uses it to sign forged status claims for certs from another CA.
///
/// Expected: `Err(OcspResponderCertNotIssuedByCa)`.
#[test]
fn ocsp_delegated_responder_wrong_ca_rejected() {
    let ca = load_cert("ocsp-delegated-ca.der");
    let leaf = load_cert("ocsp-delegated-leaf.der");
    let result = checker("ocsp-delegated-wrong-ca.der").check_revocation(&leaf, &ca);
    assert!(
        matches!(result, Err(Error::OcspResponderCertNotIssuedByCa)),
        "responder cert from a different CA must be rejected → \
         OcspResponderCertNotIssuedByCa, got: {result:?}"
    );
}

/// Delegated response where the embedded responder cert's validity
/// window ended BEFORE the response's `producedAt` time. The signing
/// key was no longer authoritative when the response was generated.
///
/// Expected: `Err(OcspResponderCertExpired)`.
#[test]
fn ocsp_delegated_responder_expired_cert_rejected() {
    let ca = load_cert("ocsp-delegated-ca.der");
    let leaf = load_cert("ocsp-delegated-leaf.der");
    let result = checker("ocsp-delegated-expired-cert.der").check_revocation(&leaf, &ca);
    assert!(
        matches!(result, Err(Error::OcspResponderCertExpired)),
        "expired responder cert must be rejected → OcspResponderCertExpired, \
         got: {result:?}"
    );
}

/// Delegated response where the issuer's signature on the embedded
/// responder cert is corrupted (last byte flipped). The OUTER OCSP
/// response signature is intact (it covers tbs_response_data, not the
/// embedded certs); only the responder-cert signature check fires.
///
/// Expected: `Err(OcspResponderCertSigInvalid)`. This must be a distinct
/// variant from `OcspSignatureInvalid` (the response's own signature) so
/// callers can tell which signature failed.
#[test]
fn ocsp_delegated_responder_bad_cert_sig_rejected() {
    let ca = load_cert("ocsp-delegated-ca.der");
    let leaf = load_cert("ocsp-delegated-leaf.der");
    let result = checker("ocsp-delegated-bad-sig.der").check_revocation(&leaf, &ca);
    assert!(
        matches!(result, Err(Error::OcspResponderCertSigInvalid)),
        "corrupted CA signature on responder cert must be rejected → \
         OcspResponderCertSigInvalid, got: {result:?}"
    );
}

/// Delegated response also works with `check_revocation_against_anchor`:
/// the same delegate-validation flow runs against the anchor's identity.
///
/// Reuses ocsp-delegated-ca.der as a trust anchor and ocsp-delegated-leaf.der
/// as the cert under check.
#[test]
fn ocsp_delegated_check_against_anchor_good() {
    let ca = load_cert("ocsp-delegated-ca.der");
    let anchor = TrustAnchor::from(&ca);
    let leaf = load_cert("ocsp-delegated-leaf.der");
    let result = checker("ocsp-delegated-good.der")
        .check_revocation_against_anchor(&leaf, &anchor);
    result.expect("valid delegated response must return Ok(()) against anchor");
}

/// `check_revocation_against_anchor` with a corrupted byKey response →
/// Err(OcspResponderIdMismatch).
///
/// Same logic as `ocsp_responder_id_bykey_wrong_rejected`: after the
/// delegated-OCSP refactor (PKIX-53kt), ResponderId matching is performed
/// during signing-key resolution, before the response signature is verified.
/// A corrupted byKey is detected at that step and returns
/// `OcspResponderIdMismatch` rather than the downstream `OcspSignatureInvalid`.
///
/// The anchor's SPKI SHA-1 must not match the corrupted hash in ocsp-rid-bad-bykey.der.
///
/// Oracle: pyca/cryptography (`gen_responder_id_fixtures.py`).
#[test]
fn ocsp_check_revocation_against_anchor_bad_responder_id() {
    let anchor_cert = load_cert("ocsp-rid-ca.der");
    let anchor = TrustAnchor::from(&anchor_cert);
    let leaf = load_cert("ocsp-rid-leaf-good.der");
    let checker = OcspChecker::new(fixture("ocsp-rid-bad-bykey.der"), NOW, DefaultVerifier)
        .expect("fixture is valid OCSP response");
    let result = checker.check_revocation_against_anchor(&leaf, &anchor);
    assert!(
        matches!(result, Err(Error::OcspResponderIdMismatch)),
        "corrupted byKey is detected during signing-key resolution → \
         OcspResponderIdMismatch, got: {result:?}"
    );
}
